                current: cursorLine,
                requestedTarget: nextSpeakableTarget,
                semanticTarget: nextSpeakableTarget,
                visualTarget: nextSpeakableTarget,
                authority: 'proof',
                proofSource: 'same_line_noop_fallback',
                sourceBranch: 'same_line_noop',
                hardContradiction: false,
